function wearableActivityCard(a){const start=new Date(a.started_at),distance=a.distance_meters==null?"":(Number(a.distance_meters)/1000).toLocaleString("pt-BR",{maximumFractionDigits:2})+" km",minutes=a.duration_seconds==null?"":Math.round(Number(a.duration_seconds)/60)+" min";return '<article class="wearable-activity"><div class="wearable-activity-icon">↗</div><div class="wearable-activity-main"><div class="wearable-activity-title"><b>'+esc(a.title)+'</b><span class="status-pill '+(a.linked_workout_id?"completed":"released")+'">'+(a.linked_workout_id?"Treino associado":"Atividade importada")+'</span></div><small>'+esc(a.sport_type)+' · '+start.toLocaleDateString("pt-BR",{day:"2-digit",month:"short"})+' · '+start.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})+'</small><div class="workout-meta">'+(minutes?'<span>◷ '+minutes+'</span>':"")+(distance?'<span>↗ '+distance+'</span>':"")+(a.average_heart_rate?'<span>♡ '+Math.round(a.average_heart_rate)+' bpm médios</span>':"")+(a.calories?'<span>⚡ '+Math.round(a.calories)+' kcal</span>':"")+'</div></div>'+(a.linked_workout_id?"":'<button class="secondary-button link-activity" data-id="'+esc(a.id)+'">Associar treino</button>')+'</article>';}
