async function openActivityLink(activityId){const {activities}=await api("/api/athlete/integrations"),activity=activities.find(a=>a.id===activityId);if(!activity){toast("Atividade não encontrada. Atualize a lista.",true);return;}const date=String(activity.started_at).slice(0,10),{workouts}=await api("/api/athlete/workouts?view=matchable&date="+encodeURIComponent(date));if(!workouts.length){toast("Não há treino liberado nesse mesmo dia para associar.",true);return;}modal("Associar atividade","Escolha o treino prescrito para o mesmo dia. A associação registra a conclusão para seu treinador.",'<form class="modal-form" id="activity-link-form"><div class="modal-field"><label for="activity-link-workout">Treino do dia</label><select id="activity-link-workout" required>'+workouts.map(w=>'<option value="'+esc(w.id)+'">'+esc(w.title)+' · '+fmt(w.workout_date)+' · '+esc(w.modality)+'</option>').join("")+'</select></div><div class="modal-actions"><button type="button" class="secondary-button" id="cancel-modal">Cancelar</button><button class="primary-button">Associar e concluir treino</button></div></form>');$("#cancel-modal").onclick=closeModal;$("#activity-link-form").onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api("/api/athlete/integrations",{method:"POST",body:JSON.stringify({action:"link-activity",provider:"strava",activityId,workoutId:$("#activity-link-workout").value})});closeModal();toast("Atividade associada e treino concluído.");navigate("integrations");}catch(err){toast(err.message,true);b.disabled=false;}};}
