function openPlan(){if(!athletes.length){toast("Adicione primeiro um atleta à equipe.",true);return;}modal("Criar ciclo de treinamento","Defina o período e o objetivo principal.",'<form class="modal-form" id="plan-form"><div class="modal-field"><label>Atleta</label><select id="p-athlete">'+athletes.map(a=>'<option value="'+a.id+'">'+esc(a.name)+'</option>').join("")+'</select></div><div class="modal-field"><label>Título do ciclo</label><input id="p-title" required maxlength="120" placeholder="Ex.: Base para meia maratona"></div><div class="detail-card"><div class="modal-field"><label>Início</label><input id="p-start" type="date" value="'+iso(new Date())+'" required></div><div class="modal-field"><label>Fim</label><input id="p-end" type="date"></div></div><div class="modal-field"><label>Objetivo e observações</label><textarea id="p-notes" maxlength="2000"></textarea></div><div class="modal-actions"><button type="button" class="secondary-button" id="cancel-modal">Cancelar</button><button class="primary-button">Criar ciclo</button></div></form>');$("#cancel-modal").onclick=closeModal;$("#plan-form").onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api("/api/trainer/plans",{method:"POST",body:JSON.stringify({athleteId:$("#p-athlete").value,title:$("#p-title").value,startDate:$("#p-start").value,endDate:$("#p-end").value,notes:$("#p-notes").value})});closeModal();toast("Ciclo criado.");navigate("workouts");}catch(err){toast(err.message,true);}finally{b.disabled=false;}};}
