async function initialize(){
 setupAuth();await loadProviders();let msg=callbackMessage();
 const hashParams=new URLSearchParams(location.hash.slice(1));
 const incomingToken=hashParams.get("convite");
 if(incomingToken){
  sessionStorage.setItem("vetra_invite_token",incomingToken);
  history.replaceState(null,"",location.pathname+location.search+"#signup");
 }
 const token=sessionStorage.getItem("vetra_invite_token");
 if(token){
  try{
   pendingInvitation=await api("/api/auth/athlete-invitation",{method:"POST",body:JSON.stringify({token})});
   pendingInviteToken=token;role="atleta";
  }catch(err){
   sessionStorage.removeItem("vetra_invite_token");sessionStorage.removeItem("vetra_invite_consent");
   pendingInvitation=null;pendingInviteToken="";msg=err.message||"Este convite não é válido ou expirou.";
  }
 }
 try{const session=await api("/api/auth/me");user=session.user;if(user){await enter();return;}}catch{}
 auth(pendingInvitation&&pendingInvitation.hasAccount?"login":"signup",msg);
}
initialize();

function openCoachReply(data){const returnPage=page;modal("Responder ao atleta",esc(data.athlete)+" · "+esc(data.title)+" · "+fmt(data.date),'<div class="reply-context"><b>Relato do atleta</b><p>'+esc(data.body)+'</p></div><form class="modal-form" id="coach-reply-form"><div class="modal-field"><label for="coach-reply-body">Sua orientação</label><textarea id="coach-reply-body" required minlength="3" maxlength="1200" placeholder="Reconheça o relato e oriente a próxima sessão.">'+esc(data.reply||"")+'</textarea></div><small class="reply-hint">Esta resposta ficará visível para o atleta na área Feedbacks.</small><div class="modal-actions"><button type="button" class="secondary-button" id="cancel-modal">Cancelar</button><button class="primary-button">Enviar resposta</button></div></form>');$("#cancel-modal").onclick=closeModal;$("#coach-reply-form").onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api("/api/trainer/feedback",{method:"POST",body:JSON.stringify({action:"reply",id:data.id,body:$("#coach-reply-body").value})});closeModal();toast("Orientação enviada ao atleta.");navigate(returnPage);}catch(err){toast(err.message,true);b.disabled=false;}};}
function confirmRelease(data){modal("Liberar treino","Confirme a sessão de "+esc(data.athlete)+" para "+fmt(data.date)+". O atleta poderá ver e registrar este treino.",'<div class="release-confirmation"><b>'+esc(data.title)+'</b><small>Treino para '+esc(data.athlete)+' · '+fmt(data.date)+'</small></div><div class="modal-actions"><button type="button" class="secondary-button" id="cancel-modal">Voltar</button><button class="primary-button" id="confirm-release">Liberar treino</button></div>');$("#cancel-modal").onclick=closeModal;$("#confirm-release").onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{await api("/api/trainer/workouts",{method:"PATCH",body:JSON.stringify({id:data.id,action:"release"})});closeModal();toast("Treino liberado para o atleta.");navigate("dashboard");}catch(err){toast(err.message,true);b.disabled=false;}};}

